import{_ as e,o as d,c as r,a0 as a}from"./chunks/framework.BTg7EidG.js";const f=JSON.parse('{"title":"Arms & Artifacts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/artifacts.md","filePath":"guide/artifacts.md"}'),o={name:"guide/artifacts.md"};function s(i,t,h,n,l,g){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="arms-artifacts" tabindex="-1">Arms &amp; Artifacts <a class="header-anchor" href="#arms-artifacts" aria-label="Permalink to &quot;Arms &amp; Artifacts&quot;">​</a></h1><p>Every hero fights with what they carry: <strong>two hand slots and three accessory slots</strong>, filled from what the world gives up. An item&#39;s stats add straight onto the wearer&#39;s own, and speed does double duty: it feeds both battle turns and how far the party marches in a day.</p><h2 id="how-the-slots-work" tabindex="-1">How the slots work <a class="header-anchor" href="#how-the-slots-work" aria-label="Permalink to &quot;How the slots work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Hands</th><th>Notes</th></tr></thead><tbody><tr><td>Blade</td><td>1</td><td>Sword, axe, or mace; pairs well with a shield</td></tr><tr><td>Dagger</td><td>1</td><td>Light steel; rogues make pairs of them sing</td></tr><tr><td>Greatblade</td><td>2</td><td>Heavy iron; warriors break the rules with these</td></tr><tr><td>Bow</td><td>2</td><td>Shooters&#39; reach on the tactical field</td></tr><tr><td>Staff</td><td>2</td><td>The caster&#39;s arm</td></tr><tr><td>Shield</td><td>1</td><td>Guard for the off hand (or the main)</td></tr><tr><td>Accessory</td><td>0</td><td>Rings, charms, and lenses; three may be worn</td></tr></tbody></table><p>Two tricks of the trade change everything about who wants what:</p><ul><li><strong>Warriors</strong> are strong enough to wield a two-handed weapon in <em>each</em> hand. Two greatblades on one veteran is the heaviest hitting in the game.</li><li><strong>Rogues</strong> shoot bows <strong>half again as hard</strong> (+50% of the bow&#39;s ranged power), and a <strong>matched pair of daggers</strong> turns them into a whirlwind: +3 melee and +1 speed on top of the steel itself.</li></ul><h2 id="where-artifacts-come-from" tabindex="-1">Where artifacts come from <a class="header-anchor" href="#where-artifacts-come-from" aria-label="Permalink to &quot;Where artifacts come from&quot;">​</a></h2><ul><li><strong>The fallen.</strong> The victor of any battle strips the dead of their gear. What your enemies carry, you can inherit.</li><li><strong>Hoards.</strong> Marauder-held buildings, and every hold the blight has swallowed, have a 40% chance of yielding an artifact when taken. A hero with <em>Plunder</em> raises that to 60%.</li><li><strong>Dungeon chests.</strong> Storming a garrisoned building on the tactical field ends at the bottom floor with a prize: coin and stores, an artifact, or on rare occasion a caged hero.</li></ul><p><strong>Geography is rarity.</strong> Treasure runs on the same menace scale as garrison muscle: the guild ring and outer wilds yield tier-1 arms, the blight&#39;s edge tier 2, and the deep blight alone gives up the tier-3 relics. Richer finds always mean harder fights.</p><p><strong>Logistics matter.</strong> New finds ride in the finding party&#39;s satchel and can be equipped by that party anywhere. The guild vault opens only inside your own cities: walk the satchel in and <strong>Store all in vault</strong> (or hold one item&#39;s chip to stow just it), or send a rogue to courier it home so another hero can draw from it. Unequipping in the field keeps the piece on the party&#39;s backs.</p><h2 id="the-catalog" tabindex="-1">The catalog <a class="header-anchor" href="#the-catalog" aria-label="Permalink to &quot;The catalog&quot;">​</a></h2><p>Every Lord sets out armed for their class: the <strong>Guildsteel Blade</strong> (⚔+2), the <strong>Ashwood Bow</strong> (🏹+2), or the <strong>Hermetic Staff</strong> (🏹+2).</p><h3 id="tier-1-·-the-ring-and-the-wilds" tabindex="-1">Tier 1 · the ring and the wilds <a class="header-anchor" href="#tier-1-·-the-ring-and-the-wilds" aria-label="Permalink to &quot;Tier 1 · the ring and the wilds&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Artifact</th><th>Type</th><th>Stats</th><th>Worth knowing</th></tr></thead><tbody><tr><td>Vitriol Edge</td><td>Blade</td><td>⚔+3</td><td>The best plain sword of the early war</td></tr><tr><td>Aurum Saber</td><td>Blade</td><td>⚔+2 🛡+1</td><td>Steel that pays its own guard</td></tr><tr><td>Cinnabar Cleaver</td><td>Blade</td><td>⚔+4 👟−1</td><td>Heavy chopping at a marching cost</td></tr><tr><td>Quicksilver Dirk</td><td>Dagger</td><td>⚔+2 👟+1</td><td>Half of a rogue&#39;s dream pair</td></tr><tr><td>Salt-Crystal Shiv</td><td>Dagger</td><td>⚔+2</td><td>The other half</td></tr><tr><td>Tin Islands Dirk</td><td>Dagger</td><td>⚔+1 👟+2</td><td>Speed in steel form</td></tr><tr><td>Leaden Maul</td><td>Greatblade</td><td>⚔+5 🛡+1 👟−1</td><td>A wall that swings</td></tr><tr><td>Aether Longbow</td><td>Bow</td><td>🏹+4</td><td>A rogue shoots this at +6</td></tr><tr><td>Reedshaft Bow</td><td>Bow</td><td>🏹+3 👟+1</td><td>Shoot and keep moving</td></tr><tr><td>Philosopher&#39;s Staff</td><td>Staff</td><td>🏹+3 🛡+1</td><td>The working alchemist&#39;s arm</td></tr><tr><td>Calcinator&#39;s Rod</td><td>Staff</td><td>🏹+2 👟+1</td><td>Keeps a frail caster out of reach</td></tr><tr><td>Salt Aegis</td><td>Shield</td><td>🛡+3</td><td>The shield wall made portable</td></tr><tr><td>Verdant Buckler</td><td>Shield</td><td>🛡+2</td><td>Cheap cover for a second line</td></tr><tr><td>Mirror of Mercury</td><td>Shield</td><td>🛡+2 👟+1</td><td>Guard without the slowing</td></tr><tr><td>Amulet of Nigredo</td><td>Accessory</td><td>🛡+2</td><td>Armor with no hands spent</td></tr><tr><td>Winged Philter</td><td>Accessory</td><td>👟+2</td><td>Faster marches for the slowest boot</td></tr><tr><td>Bezoar Charm</td><td>Accessory</td><td>🛡+1 👟+1</td><td>A little of both</td></tr><tr><td>Sharpstone Whetring</td><td>Accessory</td><td>⚔+2</td><td>An edge for any melee hand</td></tr><tr><td>Hawk&#39;s-Eye Lens</td><td>Accessory</td><td>🏹+2</td><td>A shooter&#39;s third eye</td></tr><tr><td>Tincture Bandolier</td><td>Accessory</td><td>🏹+1 👟+1</td><td>For skirmishers on the move</td></tr><tr><td>Firelime Knuckles</td><td>Accessory</td><td>⚔+1 👟+1</td><td>A brawler&#39;s quickness</td></tr></tbody></table><h3 id="tier-2-·-the-blight-s-edge" tabindex="-1">Tier 2 · the blight&#39;s edge <a class="header-anchor" href="#tier-2-·-the-blight-s-edge" aria-label="Permalink to &quot;Tier 2 · the blight&#39;s edge&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Artifact</th><th>Type</th><th>Stats</th><th>Worth knowing</th></tr></thead><tbody><tr><td>Aqua Regia Edge</td><td>Blade</td><td>⚔+4 🛡+1</td><td>The royal solvent, given a hilt</td></tr><tr><td>Nigredo Fang</td><td>Dagger</td><td>⚔+3</td><td>The pair-piece worth marching for</td></tr><tr><td>Greatsword of Sulfur</td><td>Greatblade</td><td>⚔+6</td><td>One in each warrior hand: ⚔+12</td></tr><tr><td>Entropy Reaper</td><td>Greatblade</td><td>⚔+7 🛡−1</td><td>All edge, no apology</td></tr><tr><td>Alkahest Bow</td><td>Bow</td><td>🏹+5 👟+1</td><td>+7 and change in a rogue&#39;s hands</td></tr><tr><td>Stormstring Bow</td><td>Bow</td><td>🏹+6</td><td>A rogue shoots this at +9</td></tr><tr><td>Rod of the Great Work</td><td>Staff</td><td>🏹+4</td><td>Blast fuel for the ambitious</td></tr><tr><td>Staff of the White Work</td><td>Staff</td><td>🏹+3 🛡+2</td><td>The healer-scholar&#39;s defense</td></tr><tr><td>Leaden Bulwark</td><td>Shield</td><td>🛡+4 👟−1</td><td>Bring it to a siege, not a chase</td></tr><tr><td>Ring of the Magnum Opus</td><td>Accessory</td><td>⚔+1 🛡+1</td><td>Quiet, dependable work</td></tr><tr><td>Crucible Girdle</td><td>Accessory</td><td>🛡+3</td><td>Armor for the hands-free</td></tr></tbody></table><h3 id="tier-3-·-relics-of-the-deep-blight" tabindex="-1">Tier 3 · relics of the deep blight <a class="header-anchor" href="#tier-3-·-relics-of-the-deep-blight" aria-label="Permalink to &quot;Tier 3 · relics of the deep blight&quot;">​</a></h3><p>Found only near the world&#39;s heart, where the garrisons are cruelest.</p><table tabindex="0"><thead><tr><th>Artifact</th><th>Type</th><th>Stats</th><th>Worth knowing</th></tr></thead><tbody><tr><td>The Decayer&#39;s Edge</td><td>Greatblade</td><td>⚔+10 🛡+1</td><td>The rot&#39;s own harvest blade</td></tr><tr><td>Bow of the Black Work</td><td>Bow</td><td>🏹+8 👟+1</td><td>A rogue shoots this at +12</td></tr><tr><td>Staff of the Seventh Stage</td><td>Staff</td><td>🏹+6 🛡+2</td><td>The Work&#39;s last rung</td></tr><tr><td>Aegis of the Prima Materia</td><td>Shield</td><td>🛡+6</td><td>Nothing gets through first matter</td></tr><tr><td>Philosopher&#39;s Stone Shard</td><td>Accessory</td><td>⚔+2 🏹+2 🛡+2</td><td>Everything, a little</td></tr><tr><td>Twin Fangs of Azoth</td><td>Dagger</td><td>⚔+5 👟+2</td><td>One is a weapon; two are a storm</td></tr><tr><td>Sword of Sol and Luna</td><td>Blade</td><td>⚔+6 🛡+2</td><td>A greatblade&#39;s bite in one hand</td></tr><tr><td>Crown of the Red King</td><td>Accessory</td><td>⚔+3 🛡+3</td><td>Majesty, worn into the melee</td></tr></tbody></table><h2 id="kitting-a-hero" tabindex="-1">Kitting a hero <a class="header-anchor" href="#kitting-a-hero" aria-label="Permalink to &quot;Kitting a hero&quot;">​</a></h2><ul><li>A <strong>warrior Lord</strong> wants two greatblades and armor accessories: the Entropy Reaper pair (⚔+14) with a Crucible Girdle covers the lost guard.</li><li>A <strong>rogue</strong> wants the best bow in the world plus paired daggers held in reserve, with speed accessories to strike first and slip away.</li><li>An <strong>alchemist</strong> stays alive by reach: a defensive staff, then the Winged Philter or Mirror-adjacent guard so the melee never arrives.</li><li>Remember the party marches at its <strong>slowest member&#39;s</strong> speed: one 👟−1 item on the wrong unit slows the whole column.</li></ul>',21)])])}const w=e(o,[["render",s]]);export{f as __pageData,w as default};
